import 'package:flutter/material.dart';

import '../../../themes/stack_colors.dart';
import '../../../utilities/extensions/extensions.dart';
import '../../../utilities/text_styles.dart';
import '../../../widgets/rounded_container.dart';

/// A horizontal row of selectable tag chips used to filter the address list by
/// tag. An "All" chip clears the filter. The currently selected tag is
/// highlighted. Passing a null [selectedTag] means no filter (show all).
class AddressTagFilter extends StatelessWidget {
  const AddressTagFilter({
    super.key,
    required this.tags,
    required this.selectedTag,
    required this.onSelected,
  });

  /// All distinct tags available across the wallet's addresses.
  final List<String> tags;

  /// The currently selected tag, or null when "All" is selected.
  final String? selectedTag;

  /// Called with the selected tag, or null when "All" is selected.
  final void Function(String?) onSelected;

  @override
  Widget build(BuildContext context) {
    if (tags.isEmpty) {
      return const SizedBox.shrink();
    }

    final entries = <String?>[null, ...tags];

    return SizedBox(
      height: 44,
      child: ListView.separated(
        scrollDirection: Axis.horizontal,
        itemCount: entries.length,
        separatorBuilder: (_, __) => const SizedBox(width: 8),
        itemBuilder: (_, index) {
          final tag = entries[index];
          final selected = tag == null
              ? selectedTag == null
              : selectedTag == tag;

          return _FilterChip(
            label: tag == null ? "All" : tag.capitalize(),
            selected: selected,
            onPressed: () => onSelected(tag),
          );
        },
      ),
    );
  }
}

class _FilterChip extends StatelessWidget {
  const _FilterChip({
    required this.label,
    required this.selected,
    required this.onPressed,
  });

  final String label;
  final bool selected;
  final VoidCallback onPressed;

  @override
  Widget build(BuildContext context) {
    final colors = Theme.of(context).extension<StackColors>()!;

    return RoundedContainer(
      radiusMultiplier: 0.5,
      padding: const EdgeInsets.symmetric(vertical: 5, horizontal: 12),
      color: selected ? colors.buttonBackPrimary : colors.buttonBackSecondary,
      onPressed: onPressed,
      child: Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 200),
          child: Tooltip(
            message: label,
            child: Text(
              label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: STextStyles.w500_14(context).copyWith(
                color: selected
                    ? colors.buttonTextPrimary
                    : colors.buttonTextSecondary,
              ),
            ),
          ),
        ),
      ),
    );
  }
}
